import hmac
import hashlib
import unicodedata
import os
import time
import json
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32)).encode('utf-8')
TOKEN_EXPIRY = 3600

def generate_token(user_id, role):
    """Generate an HMAC-signed authentication token."""
    timestamp = int(time.time())
    payload = f"{user_id}:{role}:{timestamp}"
    # Normalize payload for consistent signing
    normalized_payload = unicodedata.normalize('NFC', payload)
    signature = hmac.new(SECRET_KEY, normalized_payload.encode('utf-8'), hashlib.sha256).hexdigest()
    token = f"{payload}|{signature}"
    return token

def sanitize_input(raw_input):
    """Sanitize and normalize user-supplied input for safe processing."""
    if not isinstance(raw_input, str):
        return None
    # Strip control characters
    cleaned = ''.join(c for c in raw_input if unicodedata.category(c)[0] != 'C')
    # Apply compatibility normalization for consistent comparison
    normalized = unicodedata.normalize('NFKC', cleaned)
    return normalized

def extract_token_parts(token_string):
    """Parse token into payload and signature components."""
    if not token_string or '|' not in token_string:
        return None, None
    last_pipe = token_string.rfind('|')
    payload = token_string[:last_pipe]
    signature = token_string[last_pipe + 1:]
    return payload, signature

def compute_expected_signature(payload):
    """Compute the expected HMAC signature for a given payload."""
    encoded_payload = payload.encode('utf-8')
    return hmac.new(SECRET_KEY, encoded_payload, hashlib.sha256).hexdigest()

def verify_token_signature(payload, provided_signature):
    """Verify HMAC signature using constant-time comparison."""
    expected = compute_expected_signature(payload)
    return hmac.compare_digest(expected, provided_signature)

def check_token_expiry(payload):
    """Verify token has not expired."""
    parts = payload.split(':')
    if len(parts) < 3:
        return False
    try:
        timestamp = int(parts[-1])
    except (ValueError, IndexError):
        return False
    return (int(time.time()) - timestamp) < TOKEN_EXPIRY

def parse_token_claims(payload):
    """Extract claims from validated payload."""
    parts = payload.split(':')
    if len(parts) < 3:
        return None
    return {
        'user_id': parts[0],
        'role': parts[1],
        'issued_at': int(parts[2])
    }

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        raw_token = auth_header[7:]
        # Sanitize the incoming token
        clean_token = sanitize_input(raw_token)
        if clean_token is None:
            return jsonify({'error': 'Invalid token format'}), 401

        payload, signature = extract_token_parts(clean_token)
        if payload is None:
            return jsonify({'error': 'Malformed token'}), 401

        if not verify_token_signature(payload, signature):
            return jsonify({'error': 'Invalid signature'}), 403

        if not check_token_expiry(payload):
            return jsonify({'error': 'Token expired'}), 401

        claims = parse_token_claims(payload)
        if claims is None:
            return jsonify({'error': 'Invalid claims'}), 401

        g.claims = claims
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.claims.get('role') != role:
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/token', methods=['POST'])
def issue_token():
    data = request.get_json()
    if not data or 'user_id' not in data:
        return jsonify({'error': 'user_id required'}), 400
    user_id = data['user_id']
    role = data.get('role', 'user')
    token = generate_token(user_id, role)
    return jsonify({'token': token})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    return jsonify({'users': ['alice', 'bob', 'charlie']})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'profile': g.claims})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
